import React from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import SignupForm from '../components/signup/SignupForm';
import SignupVisual from '../components/signup/SignupVisual';

const Signup = () => {
    return (
        <div className="bg-background text-on-background h-screen flex flex-col overflow-hidden">
            <Header />

            {/* Main Content */}
            <main className="flex-1 flex items-center justify-center px-4 md:px-8 py-4 overflow-hidden">
                <div className="w-full max-w-6xl h-full max-h-[820px] grid grid-cols-1 md:grid-cols-2 bg-surface-container-lowest rounded-2xl border border-outline-variant overflow-hidden shadow-[0px_4px_10px_rgba(0,0,0,0.08)]">
                    <SignupVisual />
                    <SignupForm />
                </div>
            </main>

            <Footer />
        </div>
    );
};

export default Signup;
